 void rename(int index){using namespace juce;auto* dialog=new AlertWindow("Clip name","Rename this clip",MessageBoxIconType::NoIcon,this);dialog->addTextEditor("name",p.sequences()->clips[index].name);dialog->addButton("SAVE",1);dialog->addButton("CANCEL",0);auto safe=Component::SafePointer<ClipEditor>(this);dialog->enterModalState(true,ModalCallbackFunction::create([safe,index,dialog](int result){if(safe&&result==1){auto data=std::make_shared<SequencerBank>(*safe->p.sequences());data->clips[index].name=dialog->getTextEditorContents("name").substring(0,100);safe->p.setSequences(data);}}),true);}
